/** #65 real composition-root regression; invoked only from the sandboxed test. */
import { strict as assert } from "node:assert";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { bootstrap } from "../../src/cli/bootstrap.ts";
import { startSession } from "../../src/cli/sessionStart.ts";
import { createRepl } from "../../src/cli/repl.ts";
import { loadSession } from "../../src/session.ts";
import { sessionLiveness } from "../../src/mailbox/identity.ts";

process.argv = [process.argv[0]!, "neo"];
const boot = await bootstrap();
assert.notEqual(typeof boot, "number");
if (typeof boot === "number") process.exit(boot);
const s = await startSession(boot);
const repl = createRepl(s);
const old = s.sess.meta.id;
const root = s.mailbox!.root;
const oldProfile = readFileSync(join(root, old, "profile.json"), "utf8");
s.agent.messages.push({ role: "user", content: "before fork" }, { role: "assistant", content: "old reply" });
s.sess.meta.todos = [{ id: "t", content: "shared todo", status: "pending" }];
s.cfg.outputStyle = "Learning";
s.agent.mode = "auto-edit";
const permissionState = s.agent.opt.console;
// A queued /fork must never silently wait for a turn then execute.
repl.turnActive = true;
repl.submitUserLine("/fork", []);
assert.equal(repl.queue.length, 0);
assert.equal(s.sess.meta.id, old);
repl.turnActive = false;
const file = join(s.cfg.cwd, "code.txt");
writeFileSync(file, "parent code");
s.checkpoints.beforeWrite(file, "write_file");
const pending = s.rewindLog.beginTurn({ prompt: "parent turn", messagesLength: 1, checkpointSeqBefore: 0 });
s.rewindLog.endTurn(pending, s.checkpoints.list().map(e => e.seq));
const job = s.backgroundTasks!.launch({ prompt: "old task", ctx: { cfg: s.cfg, approve: async () => false }, run: async () => "do not inject" });
assert.equal(job.ok, true);
await new Promise(resolve => setTimeout(resolve, 0));
repl.queue.push({ text: "/fork", attachments: [], origin: "user" });
await repl.drain();
const child = s.sess.meta.id;
assert.notEqual(child, old);
assert.equal(s.mailbox!.sessionId, child);
assert.equal(s.agent.opt.sessionId, child);
assert.equal(s.agent.opt.console, permissionState);
assert.equal(s.agent.mode, "auto-edit");
assert.equal(s.backgroundTasks!.size, 0);
assert.deepEqual(s.agent.opt.pollBackground!(), []);
assert.equal(s.restoredJobs.length, 1);
assert.equal(s.sess.meta.backgroundTasks!.length, 1);
assert.equal(s.sess.meta.todos![0]!.content, "shared todo");
assert.equal(s.rewindLog.serialize()[0]!.checkpointSeqs.length, 0);
assert.equal(existsSync(join(s.cfg.cwd, ".neo", "backups", child)), false);
assert.match(s.agent.messages[0]!.content as string, new RegExp(s.sessionLabel!));
assert.match(s.agent.messages[0]!.content as string, /Learning|学习/);
assert.equal(readFileSync(join(root, old, "profile.json"), "utf8"), oldProfile);
assert.notEqual(sessionLiveness(root, old), "running");
assert.equal(sessionLiveness(root, child), "running");
assert.equal(loadSession(old)!.meta.outputStyle, "Learning");
const parent = readFileSync(loadSession(old)!.meta.path, "utf8");
repl.queue.push({ text: "/fork", attachments: [], origin: "user" });
await repl.drain();
assert.equal(s.sess.meta.forkedFrom, child);
assert.equal(s.sess.meta.backgroundTasks!.length, 1);
repl.queue.push({ text: "/clear", attachments: [], origin: "user" });
await repl.drain();
assert.equal(s.cfg.outputStyle, "Learning");
assert.equal(readFileSync(loadSession(old)!.meta.path, "utf8"), parent);
s.cleanupEphemeralResources();
console.log("fork-runtime-ok");
